arguments.command:
python3 - <<'EOF'
import json, glob

files = sorted(glob.glob('transcripts/*.jsonl'))
total = 0
for f in files:
    n = 0
    with open(f) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            try:
                if obj.get('payload', {}).get('role') == 'assistant':
                    n += 1
            except Exception:
                continue
    total += n
    print(f"file {f} requests {n}")
print(f"total requests {total}")
EOF
